#!/usr/bin/env bash
#
# Purpose: start Docker containers for the fullMeshExample SeedEMU output.
# Inputs: ./output/docker-compose.yml generated by compileFullMesh.sh and built images.
# Outputs: running Docker containers and ./logs/dockerBuild/dockerUp_*.log.
# Side effects: invokes the parent topology dockerUp.sh from this directory.
# Expected context: run from fullMeshExample after buildFullMesh.sh.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

if [[ ! -f ./output/docker-compose.yml ]]; then
    echo "missing ./output/docker-compose.yml; run ./compileFullMesh.sh first" >&2
    exit 1
fi

"$SCRIPT_DIR/../dockerUp.sh"
